import math
import base58

def fermat_factor(n):
    a = math.isqrt(n) + 1
    while True:
        b2 = a * a - n
        b = math.isqrt(b2)
        if b * b == b2:
            return a - b, a + b
        a += 1

def xor_decrypt(data_bytes, key_bytes):
    """Fungsi untuk dekripsi menggunakan repeating-key XOR."""
    key_length = len(key_bytes)
    decrypted = bytearray()
    for i in range(len(data_bytes)):
        decrypted_byte = data_bytes[i] ^ key_bytes[i % key_length]
        decrypted.append(decrypted_byte)
    return decrypted

